      "most_likely_effort": 24
    },
    {
      "activity_id": "A2",
      "activity_name": "Implement Restart Support for Composed Jobs",
      "activity_description": "Add functionality to restart an existing composed job, allowing users to re-launch it at will (U2).",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A3",
      "activity_name": "Investigate Kafka 0.9 Integration Options",
      "activity_description": "Research and identify areas of improvement for integrating with the 0.9 release of Kafka, including a basic proof-of-concept (U3).",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A4",
      "activity_name": "Explore Lattice Infrastructure Bootstrap",
      "activity_description": "Explore options to bootstrap and setup Lattice based infrastructure for s-c-d's bare metal deployment, including a basic setup script (U4).",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A5",
      "activity_name": "Implement Dot-Delimited Syntax for Stream Definitions",
      "activity_description": "Modify the stream definition parser to support dot-delimited syntax for resolving properties for Tuple and JSON (U5).",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A6",
      "activity_name": "Implement Tab Completion on Shell",
      "activity_description": "Add tab completion support to the s-c-d shell to allow users to interact with modules and their available options (U6).",
      "most_likely_effort": 28
    },
    {
      "activity_id": "A7",
      "activity_name": "Deploy s-c-d on Mesos",
      "activity_description": "Create deployment scripts and configurations to deploy Spring Cloud Data Flow on Mesos (U7).",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A8",
      "activity_name": "Extract Redis @Rule to Separate Repo",
      "activity_description": "Refactor and move the Redis @Rule test fixtures to a separate repository so they can be consumed in different projects (U8).",
      "most_likely_effort": 12
    }
  ],
  "reported_total": {
    "most_likely_effort": 196
  }
}
